mapper.select:
WITH updated_wallet AS (
    UPDATE wallets
    SET cash_balance = cash_balance - #{amount}
    WHERE wallet_id = #{walletId}
      AND (cash_balance - frozen_amount) >= #{amount}
        RETURNING cash_balance
)
INSERT INTO transaction_hists (
    transaction_id, trade_id, order_id, wallet_id,
    transaction_type, asset_type, direction, amount,
    balance_after, remaining_price, remaining_volume,
    created_at, fee, hash_value
)
SELECT
    #{transactionId}, #{subscriptionId}, NULL, #{walletId},
    'SUBSCRIPTION'::transaction_type_enum, 'CASH', 'OUT', #{amount},
    uw.cash_balance, 0, 0,
    NOW(), 0, #{hashValue}
FROM updated_wallet uw
RETURNING transaction_id

mapper.update:
-- 토큰 소각 WITH updates(wallet_id, token_id, amount, cash_amount, tx_id1, tx_id2, h_val1, h_val2) AS ( VALUES
( #{item.walletId}::bigint, #{item.tokenId}::bigint, #{item.amount}::numeric, #{item.cashAmount}::numeric, #{item.txId1}::bigint, #{item.txId2}::bigint, #{item.hashValue1}::text, #{item.hashValue2}::text )
), deduct_holdings AS ( -- 2. 토큰 잔액 차감 및 차감 전 보유량 반환 UPDATE holdings h SET token_balance = 0, reserved = 0, purchased_value = 0, updated_at = now() FROM updates u WHERE h.token_id = u.token_id AND h.wallet_id = u.wallet_id RETURNING h.wallet_id, h.token_id ), update_wallet AS ( -- 3. 현금 잔액 증가 UPDATE wallets w SET cash_balance = w.cash_balance + u.cash_amount, updated_at = now() FROM updates u WHERE w.wallet_id = u.wallet_id RETURNING w.wallet_id, w.cash_balance as balance_after, u.token_id ) INSERT INTO transaction_hists ( transaction_id, wallet_id, transaction_type, direction, amount, balance_after, hash_value, asset_type ) SELECT v.tx_id, u.wallet_id, 'BURN'::transaction_type_enum, v.t_dir, v.t_amt, v.t_bal, v.t_hash, v.t_asset FROM updates u JOIN update_wallet uw ON u.wallet_id = uw.wallet_id AND u.token_id = uw.token_id JOIN deduct_holdings dh ON u.wallet_id = dh.wallet_id AND u.token_id = dh.token_id CROSS JOIN LATERAL ( VALUES (u.tx_id1, 'OUT'::direction_enum, u.amount, 0, u.h_val1, 'TOKEN'::asset_type_enum), (u.tx_id2, 'IN'::direction_enum, u.cash_amount, uw.balance_after, u.h_val2, 'CASH'::asset_type_enum) ) AS v(tx_id, t_dir, t_amt, t_bal, t_hash, t_asset)
